import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{getTemplate}from"./log_object.html.js";import{Severity}from"./types.js";class LogObjectElement extends PolymerElement{static get is(){return"log-object"}static get template(){return getTemplate()}static get properties(){return{logMessage:{type:Object,observer:"logMessageChanged_"}}}logMessageChanged_(){switch(this.logMessage.severity){case Severity.WARNING:this.className="warning-log";break;case Severity.ERROR:this.className="error-log";break;case Severity.VERBOSE:this.className="verbose-log";break;default:this.className="default-log";break}}getFilenameWithLine(){if(!this.logMessage){return""}const filename=this.logMessage.file.replace("../../","//");return filename+":"+this.logMessage.line}}customElements.define(LogObjectElement.is,LogObjectElement);